\label{prop-a-number}
For a curve $C$ of genus $g$ one has $a(\operatorname{Jac}(C))=g-\operatorname{rank}(\mathcal{C})$, and the $p$-rank
of $\operatorname{Jac}(C)$ equals $\operatorname{rank}(\mathcal{C}^N)$ for $N\gg0$.

\label{lem-trinomial}
For integers $j\ge\tau+q\ge0$ with $\tau,q\ge0$,
\[
  \binom{j}{\tau}\binom{j-\tau}{q}=\frac{j!}{\tau!\,q!\,(j-\tau-q)!}
  =\binom{j}{\tau+q}\binom{\tau+q}{\tau}.
\]

\label{lem-stars}
For integers $n\ge1$ and $K\ge0$, the number of $(w_1,\dots,w_n)\in\mathbb{Z}_{\ge0}^n$ with
$w_1+\dots+w_n\le K$ is $\binom{K+n}{n}$.

The factor $x^i$ must be merged with the monomial of $f(x)^n$ \emph{before}
\eqref{eq-C2} is applied: by \eqref{eq-C1}, only $p$-th powers can be pulled through
$\mathcal{C}$. Thus the survival condition concerns the total exponent $\mu$ modulo $p$.

\label{prop-expansion}
With the notation above,
\[
  \mathcal{C}(\omega_{i,j})=\sum_{\tau=0}^{j}\ \sum_{\mathbf{n}}
  (-1)^{j-\tau}\binom{j}{\tau}\binom{n}{n_0,\dots,n_h}
  \prod_{\nu=0}^{h}\alpha_\nu^{n_\nu}\ x^{u}y^{\tau}\,dx,
\]
where $\mathbf{n}$ runs over the multi-indices with $|\mathbf{n}|=n=j-\tau$ satisfying
\eqref{eq-survival}, and
\begin{equation}\label{eq-u}
  u=L+e-1+\sum_{\nu=1}^{h}n_\nu p^{\nu-1}.
\end{equation}

The set of monomials that can occur in $\mathcal{C}(\omega_{i,j})$ does not depend on $R$;
the coefficients of $R$ enter only through the weights $\prod\alpha_\nu^{n_\nu}$,
some of which vanish when a coefficient of $R$ is zero.

\label{prop-h0}
For $h=0$, $\mathcal{C}=0$ on $H^0(C_R,\Omega^1)$; thus $\operatorname{Jac}(C_R)$ is superspecial and
$a(\operatorname{Jac}(C_R))=g=(p-1)/2$.

\label{lem-Uh-basis}
The differentials displayed in \eqref{eq-Uh} are pairwise distinct elements of
$\mathcal{B}_h$; in particular they form a basis of $\mathcal{U}_h$.

\label{lem-Uhr-basis}
Let $1\le r\le h-1$ and $m=h-r-1$.
\begin{enumerate}[label=\textup{(\roman*)}, leftmargin=2em]
  \item Every differential displayed in \eqref{eq-Uhr} belongs to $\mathcal{B}_h$.
  \item Distinct parameter tuples $(v,b,t_1,\dots,t_r,s)$ give distinct elements of
    $\mathcal{B}_h$.
\end{enumerate}
Consequently these differentials form a basis of $\mathcal{U}_h^{(r)}$, and
\begin{equation}\label{eq-dimUhr}
  \dim\mathcal{U}_h^{(r)}=p^{\,h-r-1}\binom{p+r}{r+2}.
\end{equation}

\label{thm-higher}
Let $h\ge2$ and $1\le r\le h-1$. Then $\operatorname{Im}(\mathcal{C}^r)=\mathcal{U}_h^{(r)}$, and therefore
$\operatorname{rank}(\mathcal{C}^r)=p^{\,h-r-1}\binom{p+r}{r+2}$.

\label{lem-VR}
A basis element \eqref{eq-last-basis} lies in $V_\rho$ if and only if $s\ge\rho+1$
and $b=p-1+\rho-T-2s\ge0$. Consequently $\dim V_\rho=N_{p-3-\rho}$.

\label{cor-h1}
If $h=1$ and $a_0\ne0$, then $\operatorname{rank}(\mathcal{C})=(p^2-1)/8$ and
$a(\operatorname{Jac}(C_R))=(p-1)(3p-1)/8$.

\label{thm-GT}
Let $q=p^n$ and let $X$ be a curve over $\mathbb{F}_{q^2}$. If $X$ is $\mathbb{F}_{q^2}$-maximal or
$\mathbb{F}_{q^2}$-minimal, then $\mathcal{C}^n=0$ on $H^0(X\otimes\overline{\mathbb{F}}_p,\Omega^1)$.
